// Content pack 2 — The Pacific and the Russians (authored 2026-10-17).
//
// Scope: the contest for the Northwest Coast from Bering and Chirikov in 1741 to the
// Oregon Treaty of 1846 and the sale of Alaska in 1867: the Spanish voyages and the
// Nootka Crisis, Cook and Vancouver, the Russian-American Company at Sitka, Astor's
// Pacific Fur Company and Astoria, the North West and Hudson's Bay companies in New
// Caledonia and the Columbia Department, Lewis and Clark, and the Indigenous leaders
// who dealt with all of them. Same rules as pack 1; portraits only where a likeness made
// in the person's lifetime is known to exist, and the Commons file is named for it.
import type { PackWaterway, PackExplorer, PackLink, PackLocation, PackFigure, PackTimelineEvent, PackHistoricalEvent, PackPronunciation, PackGuide, PackImage } from "./new-france-to-the-gulf";

const wiki = (slug: string) => `https://en.wikipedia.org/wiki/${slug}`;
const dcb = (slug: string) => `https://www.biographi.ca/en/bio/${slug}.html`;
const tce = (slug: string) => `https://www.thecanadianencyclopedia.ca/en/article/${slug}`;
const W = (title: string, slug: string, description: string): PackGuide => ({ title, authorSource: "Wikipedia", url: wiki(slug), description, gradeLevel: "7-9" });
const DCB = (title: string, slug: string, description: string): PackGuide => ({ title, authorSource: "Dictionary of Canadian Biography", url: dcb(slug), description, gradeLevel: "10-12" });
const TCE = (title: string, slug: string, description: string): PackGuide => ({ title, authorSource: "The Canadian Encyclopedia", url: tce(slug), description, gradeLevel: "7-9" });

export type { PackImage, PackGuide } from "./new-france-to-the-gulf";
export type PackExplorerWithPortrait = PackExplorer & { portrait?: string };
export type PackFigureWithPortrait = PackFigure & { portrait?: string };

